INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(47211, 'Psalms 52:5', 'Psalms', 52, 5, 'نو خدای به تا کړي تل دپاره نابود هغه به ونیسي تا او له خپله کوره به دې وتښتوي او ستا ریښې به د ژوندیو له دنیا وباسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms52_verse_5.mp3', '', 1761754199, 1761754199),
(47212, 'Psalms 52:6', 'Psalms', 52, 6, 'نېکان به وویني دا، شي به حیران هغوی به هغه پورې خندا کوي او وبه وایي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms52_verse_6.mp3', '', 1761754199, 1761754199),
(47213, 'Psalms 52:7', 'Psalms', 52, 7, '«وګورئ هغه زورور ته تاسو چې په خدای یې تکیه نه کړه خیر دپاره بلکې په خپلې شتمنۍ باندې تکیه کوله په بدکارۍ کې یې خپل خیر لټاوه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms52_verse_7.mp3', '', 1761754199, 1761754199),
(47214, 'Psalms 52:8', 'Psalms', 52, 8, 'خو زه یمه د زیتون د هغې ونې په شان چې د خدای کور کې راشنه کیږي هغه په ابدي مینه د خدای زه تل توکل کومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms52_verse_8.mp3', '', 1761754199, 1761754199),
(47215, 'Psalms 52:9', 'Psalms', 52, 9, 'هغو کارونو په خاطر چې تا دي کړي خدایه همېشه شکر کوم زه به اعلان کړم ستا د قوم په مخکې ستا وفادارو خلکو مخکې به اعلان وکړم چې مهربان یې خدایه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms52_verse_9.mp3', '', 1761754199, 1761754199),
(47216, 'Ezra 6:1', 'Ezra', 6, 1, 'نو داریوش پاچا یو فرمان ورکړ چې شاهي سندونه دې د بابل په ارشیف کې ولټول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_1.mp3', '', 1761754199, 1761754199),
(47217, 'Ezra 6:2', 'Ezra', 6, 2, 'خو د اکباتان د ښار په بالاحصار کې چې د ماد په ولایت کې ؤ، یو طومار وموندل شو چې په هغه کې داسې لیکل شوي وو: «دا رسمي سوانح دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_2.mp3', '', 1761754199, 1761754199),
(47218, 'Ezra 6:3', 'Ezra', 6, 3, 'کوروش پاچا د خپلې امپراتورۍ په لومړي کال امر وکړ چې په اورشلیم کې دې د خدای کور د هغه په پخواني ځای کې د قربانۍ د وړاندې کولو دپاره بیا ودان شي. هغه دې داسې جوړ شي چې اووه ویشت متره لوړوالی او اووه ویشت متره سور ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_3.mp3', '', 1761754199, 1761754199),
(47219, 'Ezra 6:4', 'Ezra', 6, 4, 'دېوالونه یې باید داسې جوړ شي چې د لویو تیږو د هرو درېو پوړونو په سر باندې دې یو پوړ لرګي وي. د هغې ټول لګښت دې د شاهي خزانې له خوا ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_4.mp3', '', 1761754199, 1761754199),
(47220, 'Ezra 6:5', 'Ezra', 6, 5, 'همدارنګه د سرو او سپینو زرو هغه لوښي چې نبوکدنصر پاچا په اورشلیم د خدای د کور څخه بابل ته راوړي وو، هغه دې بېرته په اورشلیم کې د خدای په کور کې په خپلو ځایونو کې کېښودل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_5.mp3', '', 1761754199, 1761754199),
(47221, 'Ezra 6:6', 'Ezra', 6, 6, 'نو داریوش پاچا دا لاندې ځواب ولېږه: «د فرات د سیند د لوېدیځې خوا والي تتنای، شتار بوزنای او ستاسو هغه ملګرو مامورینو ته چې د فرات د سیند په لوېدیځ کې اوسیږي: د خدای کور ته نژدې نه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_6.mp3', '', 1761754199, 1761754199),
(47222, 'Ezra 6:7', 'Ezra', 6, 7, 'د خدای د دې کور د جوړولو په کار کې لاس وهنه مه کوئ. پرېږدئ چې د یهودا والي او د یهودیانو مشران هغه کور په خپل پخواني ځای کې بېرته ودان کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_7.mp3', '', 1761754199, 1761754199),
(47223, 'Ezra 6:8', 'Ezra', 6, 8, 'زه په دې ډول تاسو ته امر کوم چې د هغوی سره د خدای د دې کور په بیا جوړولو کې مرسته وکړئ. د هغوی لګښتونه دې پوره او بې له ځنډه د هغو شاهي پیسو څخه ورکړل شي چې د مالیو له لارې د فرات د سیند د لوېدیځې خوا په ولایت کې تر لاسه شوي دي، ترڅو په کار کې ځنډ رانه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_8.mp3', '', 1761754199, 1761754199),
(47224, 'Ezra 6:9', 'Ezra', 6, 9, 'هغه څه چې کاهنان ورته په اورشلیم کې اړتیا لري یعنې سخوندران، پسونه او وري چې د اسمانونو خدای ته د سوځېدونکو نذرانو په توګه وړاندې کیږي او غنم، مالګه، شراب او د زیتونو تېل هره ورځ پرته له دې چې ځنډ په کې رامنځته شي، ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_9.mp3', '', 1761754199, 1761754199),
(47225, 'Ezra 6:10', 'Ezra', 6, 10, 'دا کارونه باید وشي، ترڅو هغوی وکولای شي هغه قربانۍ وړاندې کړي چې د اسمانونو خدای ورباندې خوشحالیږي او زما او زما د زامنو دپاره د برکت دعا وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_10.mp3', '', 1761754199, 1761754199),
(47226, 'Ezra 6:11', 'Ezra', 6, 11, 'برسېره پردې، زه امر کوم چې که څوک د دې امر نه سرغړونه وکړي، نو د هغه د کور نه دې د لرګیو یو تیر راوویستل شي، د هغه یو سر دې تېره شي او بیا دې د هغه په تن کې ومنډل شي. ورسته دې د هغه کور په ډېران باندې بدل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_11.mp3', '', 1761754199, 1761754199),
(47227, 'Ezra 6:12', 'Ezra', 6, 12, 'هغه خدای چې اورشلیم یې د خپل عبادت دپاره غوره کړی دی، هر پاچا یا هر قوم چې د دې حکم نه سرغړونه وکړي او د خدای دا کور وران کړي، خدای دې هغه له منځه یوسي. زه داریوش داسې امر کوم چې زما د امر څخه دې په پوره توګه اطاعت وشي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_12.mp3', '', 1761754199, 1761754199),
(47228, 'Ezra 6:13', 'Ezra', 6, 13, 'نو څنګه چې پاچا حکم کړی ؤ، تتنای والي، شتار بوزنای او د هغو ملګرو مامورینو کټ مټ هماغسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_13.mp3', '', 1761754199, 1761754199),
(47229, 'Ezra 6:14', 'Ezra', 6, 14, 'د یهودیانو مشرانو د خدای د کور په جوړولو کې ښه پرمختګ وکړ، ځکه چې حجي او د عیدو زوی زکریا چې نبیان وو، هغوی یې د دې کار دپاره هڅول. هغوی د اسراییلو د خدای د حکم سره سم او د فارس د پاچاهانو کوروش، داریوش او د ارتخششتا د فرمان له مخې د خدای د کور کار سرته ورساوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_14.mp3', '', 1761754199, 1761754199),
(47230, 'Ezra 6:15', 'Ezra', 6, 15, 'هغوی د داریوش د امپراتورۍ په شپږم کال د ادار د میاشتې په درېمه ورځ د خدای د دې کور کار پای ته ورساوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_15.mp3', '', 1761754199, 1761754199),
(47231, 'Ezra 6:16', 'Ezra', 6, 16, 'د اسراییلو خلکو یعنې کاهنانو، لاویانو او هغو نورو خلکو چې د جلاوطنۍ څخه راستانه شوي وو، په خوشحالۍ سره د خدای د دې د کور د وقف کېدلو جشن ولمانځه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_16.mp3', '', 1761754199, 1761754199),
(47232, 'Ezra 6:17', 'Ezra', 6, 17, 'هغوی د وقف کېدنې دپاره سل غویان، دوه سوه پسونه او څلور سوه وري قرباني کړل او دولس سېرلي یې د ټولو اسراییلو د ګناه د نذرانې په توګه قرباني کړل یعنې د هرې قبیلې په سر یو یو سېرلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_17.mp3', '', 1761754199, 1761754199),
(47233, 'Ezra 6:18', 'Ezra', 6, 18, 'هغوی د موسی د تورات د لارښوونو سره سم په اورشلیم کې د خدای د خدمت دپاره د کاهنانو او لاویانو ډلې وټاکلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_18.mp3', '', 1761754199, 1761754199),
(47234, 'Ezra 6:19', 'Ezra', 6, 19, 'هغه خلک چې د جلاوطنۍ څخه راستانه شوي وو، د لومړۍ میاشتې په څوارلسمه ورځ یې د فسحې اختر ولمانځه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_19.mp3', '', 1761754199, 1761754199),
(47235, 'Ezra 6:20', 'Ezra', 6, 20, 'ټولو کاهنانو او لاویانو خپل ځانونه پاک کړل او د مذهبي دود او دستور له مخې پاک شول. لاویانو د هغو ټولو خلکو دپاره چې د جلاوطنۍ څخه راستانه شوي وو، د نورو کاهنانو او ځانونو دپاره د فسحې د قربانیو وري حلال کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_20.mp3', '', 1761754199, 1761754199),
(47236, 'Ezra 6:21', 'Ezra', 6, 21, 'دا قربانۍ هغو اسراییلیانو وخوړلې چې د جلاوطنۍ څخه راستانه شوي وو او هغو ګاونډیانو هم وخوړلې چې د دې هېواد د نورو ناپاکو قومونو د ګناه څخه ډک رواجونه یې پریښي وو، د دې دپاره چې د اسراییلو د څښتن خدای عبادت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_21.mp3', '', 1761754199, 1761754199),
(47237, 'Ezra 6:22', 'Ezra', 6, 22, 'هغوی اووه ورځې د فطیرې ډوډۍ اختر په خوشحالۍ سره ولمانځه. د هغوی زړونه د خوشحالیو نه ډک وو، ځکه چې څښتن د آشور پاچا په هغوی باندې مهربانه کړی ؤ او د هغوی سره یې د اسراییلو د خدای د کور په بیا جوړولو کې مرسته وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra6_verse_22.mp3', '', 1761754199, 1761754199),
(47238, 'Psalms 65:1', 'Psalms', 65, 1, 'په کار ده په صهیون کې ستا ستاینه ای خدایه هغه نذرونه درکوو به کوم چې مونږ منلي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms65_verse_1.mp3', '', 1761754199, 1761754199),
(47239, 'Psalms 65:2', 'Psalms', 65, 2, 'په دې خاطر چې دعاګانې اورې انسانان ټول به ستا حضور ته راځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms65_verse_2.mp3', '', 1761754199, 1761754199),
(47240, 'Psalms 65:3', 'Psalms', 65, 3, 'کله چې زیات شي ګناهونه زما بخښې ته زما ټول جرمونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms65_verse_3.mp3', '', 1761754199, 1761754199),
(47241, 'Psalms 65:4', 'Psalms', 65, 4, 'بختور دی هغه څوک چې غوره کړی دی تا چې تاته راشي او واوسیږي ستا سپېڅلي ځای کې مونږ به ماړه شو ستا د کور په ښو شیانو باندې او ستا د معبد برکتونو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms65_verse_4.mp3', '', 1761754199, 1761754199),
(47242, 'Psalms 65:5', 'Psalms', 65, 5, 'زمونږ خدایه ته مونږ ژغورې ستا هیبتناکه عملونه راکوي ځواب زمونږ د دعا د عدالت دپاره ورکوې خلکو ته امید د دنیا هر سر کې حتی هغو ته چې اوسیږي لېرې بحرونو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms65_verse_5.mp3', '', 1761754199, 1761754199),
(47243, 'Psalms 65:6', 'Psalms', 65, 6, 'تا په قوت باندې ملا وتړله ځای په ځای کړي دي تا غرونه په خپل ځواک باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms65_verse_6.mp3', '', 1761754199, 1761754199),
(47244, 'Psalms 65:7', 'Psalms', 65, 7, 'اراموې ته د سیندونو غرهار او د څپو غړمبار اراموې ته شور او زوږ د خلکو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms65_verse_7.mp3', '', 1761754199, 1761754199),
(47245, 'Psalms 65:8', 'Psalms', 65, 8, 'تا چې کوم لویې کارنامې کړې دي ټول خلک د جهان وېریږي د نړۍ له یوه سره تر بل سره ستا کارنامې راجوړوي د خوشحالۍ نارې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms65_verse_8.mp3', '', 1761754199, 1761754199),
(47246, 'Psalms 65:9', 'Psalms', 65, 9, 'ته په ځمکه باندې پام کوې او باران وروې غني کوې یې ته او حاصلخېزوې یې ته ای خدایه سیند ستا د اوبو نه ډک دی تیاروې غلې دانې خلکو ته دا هغه څه دي چې کوې یې ته:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms65_verse_9.mp3', '', 1761754199, 1761754199),
(47247, 'Psalms 65:10', 'Psalms', 65, 10, 'په قلبه شویو ځمکو باندې ډېر زیات باران وروې نرموې ځمکه په اوبو باندې نرموې خاوره په اورښتونو باندې او شنه کوې د لویېدو دپاره ته شنه بوټي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms65_verse_10.mp3', '', 1761754199, 1761754199),
(47248, 'Psalms 65:11', 'Psalms', 65, 11, 'ستا په احسان باندې د ځمکې حاصلات شول لکه تاج د ځمکې چېرته چې ځې هرڅه پرېمانه وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms65_verse_11.mp3', '', 1761754199, 1761754199),
(47249, 'Psalms 65:12', 'Psalms', 65, 12, 'د دښتې شنې لمنې کیږي څړځایونه غني او غونډۍ سپړي د خوښۍ غوټۍ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms65_verse_12.mp3', '', 1761754199, 1761754199),
(47250, 'Psalms 65:13', 'Psalms', 65, 13, 'څړځایونه ټول وي ډک له پسونو درې دي ټولې له غنمو ډکې ټول شیان چیغې وهي او د خوښۍ ډکې سندرې وایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms65_verse_13.mp3', '', 1761754199, 1761754199),
(47251, 'Isaiah 50:1', 'Isaiah', 50, 1, 'څښتن داسې وایي: «ایا فکر کوئ چې ما داسې یئ شړلي لکه څوک چې کړي طلاقه خپله ښځه؟ نو بیا طلاق نامه ده چېرته؟ ایا فکر کوئ چې ما خرڅ کړي یئ د غلامانو په شان لکه څوک چې خرڅوي خپل اولادونه غلامانو په شان؟ نه، په سبب د ګناهونو خپلو یئ خرڅ شوي تاسو په سبب د سرغړونو خپلو یئ شړل شوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah50_verse_1.mp3', '', 1761754199, 1761754199),
(47252, 'Isaiah 50:2', 'Isaiah', 50, 2, 'چې کله راغلم ستاسو ژغورنې ته زه ولې تاسو کوم غبرګون ونه ښود؟ کله چې تاسو ما راوغوښتلئ، ولې رانه کړلو ځواب تاسو؟ ایا دومره کمزوری یم زه چې تاسو بېرته اخیستلی نه شم؟ ګورئ، زه وچومه بحیره په یو امر باندې او بدلوم سیندونه زه په دښته باندې ترڅو ماهیان مړه شي له تندې نه او بد بوی د هغوی خپور شي هرې خواته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah50_verse_2.mp3', '', 1761754199, 1761754199),
(47253, 'Isaiah 50:3', 'Isaiah', 50, 3, 'زه پوښلی شم اسمان د ویر په ټوکر او تیاره کولای شم هغه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah50_verse_3.mp3', '', 1761754199, 1761754199),
(47254, 'Isaiah 50:4', 'Isaiah', 50, 4, 'څښتن تعالی دي رازده کړي ماته چې د دې وړ شم چې ورزده یې کړمه نورو ته ترڅو قوي کړمه ستومانه خلک هر سهار راویښوي هغه ما چې غوږ ونیسم د هغه تعلیم ته د زده کوونکي په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah50_verse_4.mp3', '', 1761754199, 1761754199),
(47255, 'Isaiah 50:5', 'Isaiah', 50, 5, 'څښتن تعالی زما غوږونه خلاص کړل ما نه ده کړې سرکښي له هغه ګرځېدلی نه یم د هغه له لارې څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah50_verse_5.mp3', '', 1761754199, 1761754199),
(47256, 'Isaiah 50:6', 'Isaiah', 50, 6, 'چا چې وهلم زه ما کړله لوڅه خپله ملا هغه ته زما ږیره چې هغوی کله شکوله ما وړاندې کړ خپل مخ هغوی ته هغوی چې کله سپکولم زه او زما مخ ته یې توکولې لاړې ما ترې وانه اړوه خپل مخ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah50_verse_6.mp3', '', 1761754199, 1761754199),
(47257, 'Isaiah 50:7', 'Isaiah', 50, 7, 'څښتن تعالی دی مرستندوی زما نو ماته نه شي رسولی ضرر سپکاوی د هغوی او په خپله اراده باندې ولاړ یمه ټینګ په دې پوهېږم چې شرمنده به نه شم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah50_verse_7.mp3', '', 1761754199, 1761754199),
(47258, 'Isaiah 50:8', 'Isaiah', 50, 8, 'ځکه چې خدای نژدې دی او بې ګناهي به کړي ثابته زما څوک کولی شي جرات چې په ما تور ولګوي؟ راځئ چې لاړ شو محکمې ته څوک مدعي دی زما؟ مخامخ دې شي هغه راسره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah50_verse_8.mp3', '', 1761754199, 1761754199),
(47259, 'Isaiah 50:9', 'Isaiah', 50, 9, 'زما دفاع کوي څښتن تعالی په خپله نو بیا کولای شي څوک چې ما مجرم ثابت کړي؟ ورک به شي ټول مدعیان زما د زړو کالیو په شان لکه چینجو چې وي خوړلي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah50_verse_9.mp3', '', 1761754199, 1761754199),
(47260, 'Isaiah 50:10', 'Isaiah', 50, 10, 'ای تاسو ټول چې وېرېږئ له څښتنه او په خبرو د هغه د خدمتګار کوئ عمل په کومه لاره چې روان یې تاسو هېڅ رڼا نه لیدل کیږي خو په څښتن باندې وکړئ توکل او په خپل خدای باندې باور ولرئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah50_verse_10.mp3', '', 1761754199, 1761754199),
(47261, 'Isaiah 50:11', 'Isaiah', 50, 11, 'خو تاسو ټول چې اور بلوئ او سمبالوئ ځانونه په مشعلونو باندې د دې اور د شغلو رڼا کې تېر کړئ خپل ژوند خو په سخت عذاب کې به شئ مړه زما له لاسه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah50_verse_11.mp3', '', 1761754199, 1761754199),
(47262, 'Job 35:1', 'Job', 35, 1, 'اليهُو خپله خبره جارى وساتله او وې وئيل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_1.mp3', '', 1761754199, 1761754199),
(47263, 'Job 35:2', 'Job', 35, 2, '”ستا په خيال دا دعوىٰ به صحيح وى، چې تۀ وائى چې د خُدائ پاک په نظر کښې زۀ صادق يم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_2.mp3', '', 1761754199, 1761754199),
(47264, 'Job 35:3', 'Job', 35, 3, 'خو تۀ بيا هم د هغۀ نه تپوس کوې چې په دې کښې زما څۀ ګټه ده، او د ګناه د نۀ کولو په وجه ما ته څۀ فائده مِلاو شوې ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_3.mp3', '', 1761754199, 1761754199),
(47265, 'Job 35:4', 'Job', 35, 4, 'زۀ به تا او ستا ملګرو له جواب درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_4.mp3', '', 1761754199, 1761754199),
(47266, 'Job 35:5', 'Job', 35, 5, 'آسمان ته نظر وکړه او وګوره، هغه وريځې وګوره، کومې چې ستا نه اوچتې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_5.mp3', '', 1761754199, 1761754199),
(47267, 'Job 35:6', 'Job', 35, 6, 'کۀ تا ګناه کړې وى، نو په خُدائ پاک باندې څۀ اثر پرېوځى؟ او کۀ تۀ بار بار غلطيانې کوې، نو تۀ به د هغۀ څۀ وکړې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_6.mp3', '', 1761754199, 1761754199),
(47268, 'Job 35:7', 'Job', 35, 7, 'کۀ تۀ صادق يې، نو دې نه هغۀ ته څۀ فائده ده؟ خُدائ پاک ته ستا د يو څيز ضرورت هم نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_7.mp3', '', 1761754199, 1761754199),
(47269, 'Job 35:8', 'Job', 35, 8, 'ستا بدعملى صرف ستا په شان بنى آدم باندې اثر کوى، او ستا ښۀ عمل هم صرف په نورو بنيادمو اثر کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_8.mp3', '', 1761754199, 1761754199),
(47270, 'Job 35:9', 'Job', 35, 9, 'د ظلمونو د زياتېدو په وجه خلق فرياد کوى، او د زورَورو د ظلم په وجه د مدد دپاره چغې وهى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_9.mp3', '', 1761754199, 1761754199),
(47271, 'Job 35:10', 'Job', 35, 10, 'خو هيڅ څوک دا نۀ وائى چې خُدائ پاک زما پېدا کوونکے چرته دے؟ څوک چې د غم په وخت هم په خولۀ باندې سرودونه راولى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_10.mp3', '', 1761754199, 1761754199),
(47272, 'Job 35:11', 'Job', 35, 11, 'هغه مونږ ته د دُنيا د ځناورو نه زياته ښودنه کوى، او مونږ د هوا د مارغانو نه زيات هوښياروى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_11.mp3', '', 1761754199, 1761754199),
(47273, 'Job 35:12', 'Job', 35, 12, 'چې کله بدعمله فرياد کوى، نو خُدائ پاک د هغوئ د غرور په وجه جواب نۀ ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_12.mp3', '', 1761754199, 1761754199),
(47274, 'Job 35:13', 'Job', 35, 13, 'په حقيقت کښې خُدائ پاک بې‌مقصده فرياد نۀ اورى، او نۀ قادر خُدائ دې ته څۀ توجو ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_13.mp3', '', 1761754199, 1761754199),
(47275, 'Job 35:14', 'Job', 35, 14, 'تاسو وايئ چې تاسو خُدائ پاک نۀ وينئ، خو کۀ تاسو لږ صبر وکړئ نو هغه به د اِنصاف نه کار واخلى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_14.mp3', '', 1761754199, 1761754199),
(47276, 'Job 35:15', 'Job', 35, 15, 'تاسو وايئ چې خُدائ پاک په غصه کښې سزا نۀ ورکوى، او د بدعملۍ پرواه نۀ ساتى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_15.mp3', '', 1761754199, 1761754199),
(47277, 'Job 35:16', 'Job', 35, 16, 'ايُوبه، تۀ فضول خبرې کوې، او لکه د يو بې‌وقوف په شان خبرې کوې.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job35_verse_16.mp3', '', 1761754199, 1761754199),
(47278, 'Genesis 30:1', 'Genesis', 30, 1, 'کله چې راحیل ولیدل چې د هغې څخه د یعقوب هېڅ اولاد پیدا نه شو، نو په خپلې خور باندې یې بخیلي وکړه او یعقوب ته یې وویل: «ماته اولاد راکړه او که نه، نو زه به مړه شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_1.mp3', '', 1761754199, 1761754199),
(47279, 'Genesis 30:2', 'Genesis', 30, 2, 'یعقوب په راحیل باندې په قهر شو او ویې ویل: «زه خو خدای نه یم چې ته یې د اولاد راوړلو څخه بې‌برخې کړې یې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_2.mp3', '', 1761754199, 1761754199),
(47280, 'Genesis 30:3', 'Genesis', 30, 3, 'نو هغې وویل: «دا زما وینځه بلهه ده. د هغې سره یوځای شه، ترڅو هغه زما دپاره اولاد وزېږوي. په دې ډول به زه هم وکولای شم چې د هغې په وسیله مور شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_3.mp3', '', 1761754199, 1761754199),
(47281, 'Genesis 30:4', 'Genesis', 30, 4, 'نو خپله وینځه بلهه یې ورکړه چې د هغه ښځه شي او یعقوب د هغې سره یوځای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_4.mp3', '', 1761754199, 1761754199),
(47282, 'Genesis 30:5', 'Genesis', 30, 5, 'بلهه امیدواره شوه او یعقوب ته یې زوی وزېږاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_5.mp3', '', 1761754199, 1761754199),
(47283, 'Genesis 30:6', 'Genesis', 30, 6, 'نو راحیل وویل: «خدای زما په حق کې انصاف وکړ، هغه زما دعا قبوله کړه او ماته یې زوی راکړ.» په دې خاطر یې په هغه باندې دان نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_6.mp3', '', 1761754199, 1761754199),
(47284, 'Genesis 30:7', 'Genesis', 30, 7, 'بلهه د راحیل وینځه بیا امیدواره شوه او د هغې څخه د یعقوب دوهم زوی پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_7.mp3', '', 1761754199, 1761754199),
(47285, 'Genesis 30:8', 'Genesis', 30, 8, 'راحیل وویل: «د خپلې خور سره مې سخته شخړه وکړه او زه بریالۍ شوې یم.» نو ځکه یې په هغه باندې نفتالي نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_8.mp3', '', 1761754199, 1761754199),
(47286, 'Genesis 30:9', 'Genesis', 30, 9, 'کله چې لیه پوه شوه چې د اولاد راوړلو څخه ولوېدله، نو خپله وینځه زلفه یې یعقوب ته ورکړه چې د هغه ښځه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_9.mp3', '', 1761754199, 1761754199),
(47287, 'Genesis 30:10', 'Genesis', 30, 10, 'د لیه د وینځې زلفې څخه د یعقوب زوی پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_10.mp3', '', 1761754199, 1761754199),
(47288, 'Genesis 30:11', 'Genesis', 30, 11, 'لیه وویل: «زه بختوره یم.» نو ځکه یې په هغه باندې جاد نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_11.mp3', '', 1761754199, 1761754199),
(47289, 'Genesis 30:12', 'Genesis', 30, 12, 'د لیه د وینځې زلفې څخه د یعقوب بل زوی پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_12.mp3', '', 1761754199, 1761754199),
(47290, 'Genesis 30:13', 'Genesis', 30, 13, 'لیه وویل: «زه څومره خوشحاله یم! ټولې ښځې به ماته خوشحاله وایي.» نو په هغه باندې یې اشیر نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_13.mp3', '', 1761754199, 1761754199),
(47291, 'Genesis 30:14', 'Genesis', 30, 14, 'د غنمو د لو کولو په وخت کې روبین پټیو ته لاړ او هلته یې مړه‌غونې یې وموندلې. هغه یې خپلې مور لیه ته راوړلې. راحیل لیه ته وویل: «د خپل زوی د مړه‌غونو څخه یو څه ماته راکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_14.mp3', '', 1761754199, 1761754199),
(47292, 'Genesis 30:15', 'Genesis', 30, 15, 'خو لیه هغې ته ځواب ورکړ: «ایا دا دې بس نه دی چې مېړه دې راڅخه واخیست؟ اوس غواړې چې زما د زوی مړه‌غونې هم راڅخه واخلې؟» راحیل وویل: «ډېر ښه، هغه به نن شپه ستا د زوی د مړه‌غونو په بدل کې ستا سره څملي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_15.mp3', '', 1761754199, 1761754199),
(47293, 'Genesis 30:16', 'Genesis', 30, 16, 'نو کله چې ماښام یعقوب د پټیو څخه راغی، لیه د هغه مخې ته ورووتله. هغه ته یې وویل: «ته باید نن شپه زما سره څملې، ځکه چې د خپل زوی د مړه‌غونو په بدل کې مې اخیستی یې.» نو یعقوب په هغه شپه له لیه سره څملاست.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_16.mp3', '', 1761754199, 1761754199),
(47294, 'Genesis 30:17', 'Genesis', 30, 17, 'خدای د لیه دعا قبوله کړه او هغه امیدواره شوه او د هغې څخه د یعقوب پنځم زوی پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_17.mp3', '', 1761754199, 1761754199),
(47295, 'Genesis 30:18', 'Genesis', 30, 18, 'لیه وویل: «په دې خاطر چې ما خپله وینځه خپل مېړه ته ورکړه، خدای ماته اجر راکړ.» نو په هغه باندې یې یساکار نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_18.mp3', '', 1761754199, 1761754199),
(47296, 'Genesis 30:19', 'Genesis', 30, 19, 'لیه بیا امیدواره شوه او یعقوب ته یې شپږم زوی وزېږاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_19.mp3', '', 1761754199, 1761754199),
(47297, 'Genesis 30:20', 'Genesis', 30, 20, 'هغې وویل: «خدای ماته ښه قیمتي سوغات راکړ. اوس به مې مېړه عزت کوي، ځکه چې شپږ زامن مې ورته زېږولي دي.» نو په هغه باندې یې زبولون نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_20.mp3', '', 1761754199, 1761754199),
(47298, 'Genesis 30:21', 'Genesis', 30, 21, 'وروسته له هغه یې لور پیدا شوه او په هغې یې دینه نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_21.mp3', '', 1761754199, 1761754199),
(47299, 'Genesis 30:22', 'Genesis', 30, 22, 'بیا خدای راحیل رایاده کړه، د هغې دعا یې قبوله کړه او هغې ته یې اولاد ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_22.mp3', '', 1761754199, 1761754199),
(47300, 'Genesis 30:23', 'Genesis', 30, 23, 'هغه امیدواره شوه او زوی یې وزېږاوه. هغې وویل: «خدای زما رسوایي لېرې کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_23.mp3', '', 1761754199, 1761754199),
(47301, 'Genesis 30:24', 'Genesis', 30, 24, 'نو په هغه باندې یې یوسف نوم کېښود او ویې ویل: «څښتن دې بل زوی راته راکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_24.mp3', '', 1761754199, 1761754199),
(47302, 'Genesis 30:25', 'Genesis', 30, 25, 'وروسته له هغې چې راحیل یوسف وزېږاوه، یعقوب لابان ته وویل: «ما رخصت کړه چې بېرته خپل وطن ته لاړ شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_25.mp3', '', 1761754199, 1761754199),
(47303, 'Genesis 30:26', 'Genesis', 30, 26, 'زما ښځې او زما اولادونه چې د هغوی دپاره مې ستا خدمت کړی دی ماته راکړه چې لاړ شم، ځکه ته پوهېږې چې څومره کار مې درته کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_26.mp3', '', 1761754199, 1761754199),
(47304, 'Genesis 30:27', 'Genesis', 30, 27, 'خو لابان هغه ته وویل: «که ته زما څخه خوشحاله یې، مهرباني وکړه پاتې شه. زه د فال په وسیله پوه شوم چې څښتن ستا په خاطر ماته برکت راکړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_27.mp3', '', 1761754199, 1761754199),
(47305, 'Genesis 30:28', 'Genesis', 30, 28, 'خپله مزدوري دې ووایه، زه به یې درکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_28.mp3', '', 1761754199, 1761754199),
(47306, 'Genesis 30:29', 'Genesis', 30, 29, 'یعقوب هغه ته وویل: «ته پوهېږې چې څنګه مې درته کار کړی دی او څنګه مې ستا رمې او پادې ساتلې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_29.mp3', '', 1761754199, 1761754199),
(47307, 'Genesis 30:30', 'Genesis', 30, 30, 'زما د راتللو څخه مخکې تا لږ څه درلودل، خو کوم کارونه چې ما ستا دپاره کړي دي څښتن په هغو کې برکت اچولی دی او ستا شتمني ډېره زیاته شوې ده. اوس د دې وخت رارسېدلی چې د خپلې کورنۍ دپاره یو څه وکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_30.mp3', '', 1761754199, 1761754199),
(47308, 'Genesis 30:31', 'Genesis', 30, 31, 'لابان پوښتنه وکړه: «څه درکړم؟» یعقوب ځواب ورکړ: «ماته هېڅ شی مه راکوه. که دا کار زما دپاره وکړې زه به ستا د رمو ساتلو او روزلو ته دوام ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_31.mp3', '', 1761754199, 1761754199),
(47309, 'Genesis 30:32', 'Genesis', 30, 32, 'اجازه راکړه چې نن ستا د ټولو رمو په منځ کې وګرځم او د مېږو څخه هره یوه خالداره مېږه او هر توربخن وری او د وزو څخه هره خالداره وزه بېله کړم، نو دا به زما مزدوري وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_32.mp3', '', 1761754199, 1761754199),
(47310, 'Genesis 30:33', 'Genesis', 30, 33, 'کله چې راشې او هغه مزدوري چې ماته یې راکوې وګورې، نو په اسانۍ سره به درته معلومه شي چې زه صادق یم. که چېرې زما سره کومه وزه چې خالداره نه وي یا یو وری چې توربخن نه وي، نو ته به پوه شې چې هغه غلا شوی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis30_verse_33.mp3', '', 1761754199, 1761754199);